import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs'; import os from 'node:os'; import path from 'node:path';
import { createServer } from '../../src/server.js';
test('create and read a page', async () => {
  const srv = createServer({ dataDir: fs.mkdtempSync(path.join(os.tmpdir(), 'wiki-')) }); await new Promise(r => srv.listen(0, r));
  const base = `http://127.0.0.1:${srv.address().port}`;
  const put = await fetch(base + '/api/pages/home', { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: 'Home', body: '# Welcome' }) });
  assert.equal(put.status, 201);
  const page = await (await fetch(base + '/api/pages/home')).json();
  assert.match(page.html, /<h1 id="welcome">Welcome<\/h1>/);
  srv.close();
});
rtool - logged retrieval helper for the reuse-first / hybrid conditions.

Every invocation appends one JSON line to $BENCH_TELEMETRY_DIR/retrieval.jsonl
(default ./.telemetry) with the command, arguments, wall time, success flag,
number of results returned, bytes and lines acquired, and source URLs. The
harness joins these records with the model transcript.

commands: gh-search, gh-code-search, so-search, so-answers, npm-search, npm-fetch, clone, fetch

