    const url = new URL(req.url, 'http://localhost');
    let parts;
    try {
      parts = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
    } catch {
      throw bad('Malformed URL');
    }
    const method = req.method;
    const q = url.searchParams;

    // UI
